// Run with output/vector-fixture generated by forecast.py --max-frames 2.
(async function(){
 const pause=ms=>new Promise(r=>setTimeout(r,ms)),assert=(ok,m)=>{if(!ok)throw Error(m);};
 async function until(f){for(let i=0;i<300;i++){if(f())return;await pause(30);}throw Error('Vector/Live map did not settle');}
 const now=Date.now(),reading=value=>({value,time:now-300000});
 const fixtures={schema:1,checked:new Date(now).toISOString(),stations:[{id:'met-501',name:'Shared-map wind',lat:60.85,lon:17.583333,readings:{wind:reading(7.2),windDirection:reading(240)}},{id:'sea-502',name:'Shared-map buoy',lat:61,lon:17.6,readings:{wave:reading(1.4)}}]};
 const original=window.fetch;
 window.fetch=(url,options)=>String(url).includes('/live-data/')?Promise.resolve(new Response(JSON.stringify(fixtures))):String(url).includes('opendata-download-')?Promise.resolve(new Response('',{status:503})):original(url,options);
 try{
  const j=await(await fetch('/output/vector-fixture/run.json')).json();j.imageBase=location.origin+'/output/vector-fixture/plots/';refreshRun(j);window.fetchRunInfo=()=>Promise.resolve(j);
  if(!ForecastMap.active())document.querySelector('#forecast-map-launch').click();
  await until(()=>document.querySelector('#forecast-map svg[data-identity]'));
  const svg=()=>document.querySelector('#forecast-map svg[data-identity]'),arrow=()=>svg().querySelector('[data-arrow]'),size=()=>{const m=arrow().getScreenCTM();return Math.hypot(m.a,m.b);};
  assert(!svg().querySelector('image'),'Forecast contains an embedded bitmap');assert(svg().querySelectorAll('path').length>10,'Vector bands missing');
  const oldSize=size(),pane=document.querySelector('#forecast-map'),mapId=pane._leaflet_id,mapRect=pane.getBoundingClientRect();
  document.querySelector('#forecast-map .leaflet-control-zoom-in').click();await pause(350);assert(Math.abs(size()-oldSize)<.2,'Arrows grow with map zoom');
  while(ForecastMap.view().zoom<8){pane.querySelector('.leaflet-control-zoom-in').click();await pause(350);}
  await show(displayedFrame.index===1?2:1);
  const view=ForecastMap.view(),pixelDegrees=360/256/Math.pow(2,ForecastMap.view().zoom),hour=displayedFrame.index;
  const stamp=Date.parse(forecast.frames[hour-1].time);
  const link=mode=>pane.closest('section').querySelector('#forecast-map-quantities a[data-quantity="'+mode+'"]');
  assert(link(1).href.includes('map=waves')&&Date.parse(new URL(link(1).href).searchParams.get('time'))===stamp,'Waves page link omits its mode or hour');
  document.querySelector('#forecast-map-quantities [data-quantity=live]').click();document.querySelector('#forecast-map-refresh').click();
  await until(()=>pane.querySelector('[data-station="sea-502"]'));await pause(100);
  assert(pane._leaflet_id===mapId,'Live creates a different map');assert(pane.getBoundingClientRect().height>mapRect.height&&Math.abs(pane.getBoundingClientRect().top-mapRect.top)<1,'Live does not use the room freed by the forecast controls');assert(document.querySelector('#bar').inert,'Hidden Live slider is still interactive');assert(getComputedStyle(document.querySelector('#bar')).display==='none','Live keeps the time slider');
  assert(ForecastMap.view().zoom===view.zoom&&Math.abs(ForecastMap.view().lat-view.lat)<pixelDegrees&&Math.abs(ForecastMap.view().lon-view.lon)<pixelDegrees,'Live changes map position');
  pane.querySelector('[data-station="sea-502"]').click();await until(()=>document.querySelector('#live-sheet').open);
  assert(document.querySelector('#live-title').textContent==='Shared-map buoy','Station tap opens wrong details');
  assert(document.querySelector('#live-tabs [data-tab=map]').hidden&&document.querySelector('#live-forecast').hidden,'Shared station shows a duplicate map return or a shortcut without a saved point');
  document.querySelector('#live-close').click();await pause(100);
  assert(!document.querySelector('#live-sheet').open&&document.body.classList.contains('forecast-map-live-mode'),'Station return leaves shared map');
  assert(!new URL(location.href).searchParams.has('station'),'Live map URL still opens a station');
  document.querySelector('#forecast-map-quantities [data-quantity="2"]').click();await until(()=>svg()?.dataset.kind==='hsw');await pause(100);
  assert(getComputedStyle(document.querySelector('#bar')).visibility!=='hidden','Forecast does not restore slider');assert(displayedFrame.index===hour,'Live changes forecast hour');assert(ForecastMap.view().zoom===view.zoom&&Math.abs(ForecastMap.view().lat-view.lat)<pixelDegrees,'Forecast return changes map position '+JSON.stringify({before:view,after:ForecastMap.view()}));
  assert(!pane.querySelector('[data-station]'),'Station markers remain over forecast');assert(!svg().querySelector('image'),'Swell is not vector');
  history.back();await until(()=>link('live').getAttribute('aria-current')==='page');
  assert(Date.parse(new URL(location.href).searchParams.get('time'))===stamp,'Back to Live loses the pinned hour');
  history.forward();await until(()=>link(2).getAttribute('aria-current')==='page'&&svg()?.dataset.kind==='hsw');
  assert(displayedFrame.index===hour&&pane._leaflet_id===mapId,'History navigation loses map or hour');
  await ForecastOpenPoint(60.95,17.416667,2);
  const pointSheet=document.querySelector('#point-sheet'),place=document.querySelector('#point-location');
  await until(()=>pointSheet.open&&!document.querySelector('#point-content').hidden);
  const lastLocation=place.textContent;
  document.querySelector('#point-close').click();await until(()=>!document.querySelector('#forecast-map-details').hidden);
  link('live').click();await until(()=>pane.querySelector('[data-station="sea-502"]'));
  assert(!document.querySelector('#forecast-map-details').hidden,'Live map hides the last forecast point');
  pane.querySelector('[data-station="sea-502"]').click();
  const shortcut=document.querySelector('#live-forecast');
  await until(()=>document.querySelector('#live-sheet').open&&!shortcut.hidden);
  assert(shortcut.textContent==='Last forecast point','Shortcut does not identify the last forecast point');
  shortcut.click();await until(()=>pointSheet.open&&!document.querySelector('#point-content').hidden);
  assert(place.textContent===lastLocation&&displayedFrame.index===hour,'Shortcut loses the last location or forecast hour');
  assert(getComputedStyle(document.querySelector('#point-view-live')).display==='none','Forecast details still offer two map exits');
  assert(document.querySelector('#point-close').textContent==='← Back','Forecast exit is not labelled Back');
  document.querySelector('#point-reading button[data-quantity="1"]').click();
  const nextHour=hour===1?2:1;
  document.querySelector(hour===1?'#point-next':'#point-prev').click();
  document.querySelector('#point-close').click();
  await until(()=>link(1).getAttribute('aria-current')==='page'&&svg()?.dataset.kind==='hs'&&displayedFrame.index===nextHour);
  return {trueSVG:true,fixedArrowSize:true,sameMap:true,liveHidesSlider:true,stationDetails:true,forecastRestoresTimeAndPosition:true,modeHistory:true,lastForecastPoint:true,backUsesSelectedQuantityAndHour:true};
 }finally{window.fetch=original;if(document.querySelector('#live-sheet').open)document.querySelector('#live-close').click();}
})();
